class Solution {
public:
    int maximumXOR(std::vector<int>& nums) {
        int ans = 0;
        for (int x : nums) ans |= x;
        return ans;
    }
};

class Solution {
    public int maximumXOR(int[] nums) {
        int ans = 0;
        for (int x : nums) ans |= x;
        return ans;
    }
}

var maximumXOR = function(nums) {
    let ans = 0;
    for (let i = 0; i < nums.length; i++) ans |= nums[i];
    return ans;
};
